 68	package com.pousada.api;
 69	
 70	import com.google.gson.Gson;
 71	import com.pousada.api.dto.CreateReservationRequest;
 72	import com.pousada.api.dto.ErrorResponse;
 73	import com.pousada.models.Message;
 74	import com.pousada.models.Receipt;
 75	import com.pousada.models.Reservation;
 76	import com.pousada.models.Room;
 77	import com.pousada.repositories.MessageRepository;
 78	import com.pousada.repositories.ReservationRepository;
 79	import com.pousada.repositories.RoomRepository;
 80	import com.pousada.services.MessageService;
 81	import com.pousada.services.ReceiptService;
 82	import com.pousada.services.ReportService;
 83	import com.pousada.services.ReservationService;
 84	import com.pousada.utils.FormatterUtil;
 85	import io.javalin.Javalin;
 86	import java.math.BigDecimal;
 87	import java.time.LocalDate;
 88	import java.time.YearMonth;
 89	import java.util.List;
 90	
 91	public class ApiController {
 92	    private final Gson gson;
 93	    private final RoomRepository roomRepository;
 94	    private final ReservationRepository reservationRepository;
 95	    private final MessageRepository messageRepository;
 96	    private final ReservationService reservationService;
 97	    private final MessageService messageService;
 98	    private final ReceiptService receiptService;
 99	    private final ReportService reportService;
100	
101	    public ApiController(Javalin app, Gson gson, RoomRepository roomRepository,
102	                        ReservationRepository reservationRepository, MessageRepository messageRepository,
103	                        ReservationService reservationService, MessageService messageService,
104	                        ReceiptService receiptService, ReportService reportService) {
105	        this.gson = gson;
106	        this.roomRepository = roomRepository;
107	        this.reservationRepository = reservationRepository;
108	        this.messageRepository = messageRepository;
109	        this.reservationService = reservationService;
110	        this.messageService = messageService;
111	        this.receiptService = receiptService;
112	        this.reportService = reportService;
113	
114	        setupRoutes(app);
115	    }
116	
117	    private void setupRoutes(Javalin app) {
118	        app.get("/rooms", this::listRooms);
119	        app.post("/reservations", this::createReservation);
120	        app.get("/reservations/{id}", this::getReservation);
121	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
122	        app.post("/reservations/{id}/check-in", this::checkIn);
123	        app.post("/reservations/{id}/check-out", this::checkOut);
124	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
125	        app.get("/reservations/{id}/document", this::getDocument);
126	        app.get("/messages", this::listMessages);
127	        app.get("/reports/occupancy", this::getOccupancyReport);
128	        app.get("/reports/revenue", this::getRevenueReport);
129	    }
130	
131	    private void listRooms(io.javalin.http.Context ctx) throws Exception {
132	        List<Room> rooms = roomRepository.findAll();
133	        ctx.json(rooms.stream().map(ApiMapper::mapRoom).toList());
134	    }
135	
136	    private void createReservation(io.javalin.http.Context ctx) throws Exception {
137	        try {
138	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
139	
140	            if (req.getRoomNumber() == null || req.getGuestName() == null || req.getGuestEmail() == null ||
141	                req.getGuestCpf() == null || req.getCheckIn() == null || req.getCheckOut() == null ||
142	                req.getGuests() == null || req.getRatePlan() == null) {
143	                ctx.status(400);
144	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
145	                return;
146	            }
147	
148	            Room room = roomRepository.findByNumber(req.getRoomNumber());
149	            if (room == null) {
150	                ctx.status(404);
151	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
152	                return;
153	            }
154	
155	            LocalDate checkIn = FormatterUtil.parseDate(req.getCheckIn());
156	            LocalDate checkOut = FormatterUtil.parseDate(req.getCheckOut());
157	
158	            if (!checkIn.isBefore(checkOut)) {
159	                ctx.status(400);
160	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
161	                return;
162	            }
163	
164	            if (req.getGuests() < 1) {
165	                ctx.status(400);
166	                ctx.json(new ErrorResponse("INVALID_REQUEST", "At least one guest required"));
167	                return;
168	            }
169	
170	            if (req.getGuests() > room.getCapacity()) {
171	                ctx.status(422);
172	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Room capacity exceeded"));
173	                return;
174	            }
175	
176	            if (!reservationRepository.isRoomAvailable(req.getRoomNumber(), checkIn, checkOut)) {
177	                ctx.status(409);
178	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
179	                return;
180	            }
181	
182	            Reservation reservation = reservationService.createReservation(
183	                req.getRoomNumber(),
184	                req.getGuestName(),
185	                req.getGuestEmail(),
186	                req.getGuestCpf(),
187	                checkIn,
188	                checkOut,
189	                req.getGuests(),
190	                req.getRatePlan()
191	            );
192	
193	            ctx.status(201);
194	            ctx.json(ApiMapper.mapReservation(reservation));
195	        } catch (IllegalArgumentException e) {
196	            ctx.status(400);
197	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
198	        } catch (Exception e) {
199	            ctx.status(400);
200	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
201	        }
202	    }
203	
204	    private void getReservation(io.javalin.http.Context ctx) throws Exception {
205	        Long id = Long.valueOf(ctx.pathParam("id"));
206	        Reservation reservation = reservationRepository.findById(id);
207	
208	        if (reservation == null) {
209	            ctx.status(404);
210	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
211	            return;
212	        }
213	
214	        ctx.json(ApiMapper.mapReservation(reservation));
215	    }
216	
217	    private void confirmReservation(io.javalin.http.Context ctx) throws Exception {
218	        try {
219	            Long id = Long.valueOf(ctx.pathParam("id"));
220	            Reservation reservation = reservationRepository.findById(id);
221	
222	            if (reservation == null) {
223	                ctx.status(404);
224	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
225	                return;
226	            }
227	
228	            if (!"PENDING".equals(reservation.getStatus())) {
229	                ctx.status(409);
230	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot confirm a non-pending reservation"));
231	                return;
232	            }
233	
234	            BigDecimal amountPaid = reservation.getTotal();
235	            Reservation confirmed = reservationService.confirmReservation(id, amountPaid);
236	
237	            Receipt receipt = receiptService.generateReceipt(confirmed);
238	            String receiptText = receiptService.formatReceipt(receipt);
239	
240	            messageService.sendConfirmationEmail(confirmed.getGuestName(), confirmed.getGuestEmail(), receiptText);
241	
242	            ctx.json(ApiMapper.mapReservation(confirmed));
243	        } catch (IllegalStateException e) {
244	            ctx.status(409);
245	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
246	        }
247	    }
248	
249	    private void checkIn(io.javalin.http.Context ctx) throws Exception {
250	        try {
251	            Long id = Long.valueOf(ctx.pathParam("id"));
252	            Reservation reservation = reservationRepository.findById(id);
253	
254	            if (reservation == null) {
255	                ctx.status(404);
256	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
257	                return;
258	            }
259	
260	            if (!"CONFIRMED".equals(reservation.getStatus())) {
261	                ctx.status(409);
262	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check in a non-confirmed reservation"));
263	                return;
264	            }
265	
266	            Reservation checkedIn = reservationService.checkIn(id);
267	            ctx.json(ApiMapper.mapReservation(checkedIn));
268	        } catch (IllegalStateException e) {
269	            ctx.status(409);
270	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
271	        }
272	    }
273	
274	    private void checkOut(io.javalin.http.Context ctx) throws Exception {
275	        try {
276	            Long id = Long.valueOf(ctx.pathParam("id"));
277	            Reservation reservation = reservationRepository.findById(id);
278	
279	            if (reservation == null) {
280	                ctx.status(404);
281	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
282	                return;
283	            }
284	
285	            if (!"CHECKED_IN".equals(reservation.getStatus())) {
286	                ctx.status(409);
287	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check out a non-checked-in reservation"));
288	                return;
289	            }
290	
291	            Reservation checkedOut = reservationService.checkOut(id);
292	            Receipt receipt = receiptService.generateReceipt(checkedOut);
293	
294	            ctx.json(ApiMapper.mapReceipt(receipt));
295	        } catch (IllegalStateException e) {
296	            ctx.status(409);
297	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
298	        }
299	    }
300	
301	    private void cancelReservation(io.javalin.http.Context ctx) throws Exception {
302	        try {
303	            Long id = Long.valueOf(ctx.pathParam("id"));
304	            Reservation reservation = reservationRepository.findById(id);
305	
306	            if (reservation == null) {
307	                ctx.status(404);
308	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
309	                return;
310	            }
311	
312	            String status = reservation.getStatus();
313	            if (!"PENDING".equals(status) && !"CONFIRMED".equals(status)) {
314	                ctx.status(409);
315	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot cancel a reservation in this status"));
316	                return;
317	            }
318	
319	            Reservation cancelled = reservationService.cancelReservation(id);
320	            ctx.json(ApiMapper.mapReservation(cancelled));
321	        } catch (IllegalStateException e) {
322	            ctx.status(409);
323	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
324	        }
325	    }
326	
327	    private void getDocument(io.javalin.http.Context ctx) throws Exception {
328	        Long id = Long.valueOf(ctx.pathParam("id"));
329	        Reservation reservation = reservationRepository.findById(id);
330	
331	        if (reservation == null) {
332	            ctx.status(404);
333	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
334	            return;
335	        }
336	
337	        if (!"CONFIRMED".equals(reservation.getStatus()) &&
338	            !"CHECKED_IN".equals(reservation.getStatus()) &&
339	            !"CHECKED_OUT".equals(reservation.getStatus())) {
340	            ctx.status(409);
341	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for confirmed reservations"));
342	            return;
343	        }
344	
345	        Receipt receipt = receiptService.generateReceipt(reservation);
346	        ctx.json(ApiMapper.mapReceipt(receipt));
347	    }
348	
349	    private void listMessages(io.javalin.http.Context ctx) throws Exception {
350	        List<Message> messages = messageRepository.findAll();
351	        ctx.json(messages.stream().map(ApiMapper::mapMessage).toList());
352	    }
353	
354	    private void getOccupancyReport(io.javalin.http.Context ctx) throws Exception {
355	        String dateParam = ctx.queryParam("date");
356	        if (dateParam == null) {
357	            ctx.status(400);
358	            ctx.json(new ErrorResponse("INVALID_REQUEST", "date parameter is required"));
359	            return;
360	        }
361	
362	        try {
363	            LocalDate date = FormatterUtil.parseDate(dateParam);
364	            String report = reportService.getOccupancyReport(date);
365	            ctx.contentType("text/csv;charset=utf-8");
366	            ctx.result(report);
367	        } catch (Exception e) {
368	            ctx.status(400);
369	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
370	        }
371	    }
372	
373	    private void getRevenueReport(io.javalin.http.Context ctx) throws Exception {
374	        String monthParam = ctx.queryParam("month");
375	        if (monthParam == null) {
376	            ctx.status(400);
377	            ctx.json(new ErrorResponse("INVALID_REQUEST", "month parameter is required"));
378	            return;
379	        }
380	
381	        try {
382	            YearMonth ym = YearMonth.parse(monthParam);
383	            String report = reportService.getRevenueReport(ym.getYear(), ym.getMonthValue());
384	            ctx.contentType("text/csv;charset=utf-8");
385	            ctx.result(report);
386	        } catch (Exception e) {
387	            ctx.status(400);
388	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format (use YYYY-MM)"));
389	        }
390	    }
391	}

