120	public class ReportService {
121	    private final ReservationRepository reservationRepository;
122	    private final RoomRepository roomRepository;
123	
124	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
125	        this.reservationRepository = reservationRepository;
126	        this.roomRepository = roomRepository;
127	    }
128	
129	    public String getOccupancyReport(LocalDate date) throws Exception {
130	        List<Room> allRooms = roomRepository.findAll();
131	        StringBuilder csv = new StringBuilder();
132	
133	        csv.append("room,type,reservation,check_in,check_out\n");
134	
135	        int occupiedCount = 0;
136	
137	        for (Room room : allRooms) {
138	            List<Reservation> reservations = reservationRepository.findByRoomAndNight(room.getNumber(), date);
139	
140	            if (reservations.isEmpty()) {
141	                continue;
142	            }
143	
144	            for (Reservation res : reservations) {
145	                csv.append(res.getRoomNumber()).append(",");
146	                csv.append(room.getType()).append(",");
147	                csv.append(res.getId()).append(",");
148	                csv.append(FormatterUtil.formatDateISO(res.getCheckIn())).append(",");
149	                csv.append(FormatterUtil.formatDateISO(res.getCheckOut())).append("\n");
150	            }
151	
152	            occupiedCount++;
153	        }
154	
155	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size()).append("\n");
156	
157	        return csv.toString();
158	    }
159	
160	    public String getRevenueReport(int year, int month) throws Exception {
161	        List<Reservation> reservations = reservationRepository.findByMonthAndNotCancelled(year, month);
162	        StringBuilder csv = new StringBuilder();
163	
164	        csv.append("reservation,room,check_in,check_out,status,amount\n");
165	
166	        BigDecimal totalAmount = BigDecimal.ZERO;
167	
168	        for (Reservation res : reservations) {
169	            BigDecimal revenue = res.getAmountPaid();
170	            if (res.getRefund() != null) {
171	                revenue = revenue.subtract(res.getRefund());
172	            }
173	
174	            csv.append(res.getId()).append(",");
175	            csv.append(res.getRoomNumber()).append(",");
176	            csv.append(FormatterUtil.formatDateISO(res.getCheckIn())).append(",");
177	            csv.append(FormatterUtil.formatDateISO(res.getCheckOut())).append(",");
178	            csv.append(res.getStatus()).append(",");
179	            csv.append(FormatterUtil.formatCurrencyCSV(revenue)).append("\n");
180	
181	            totalAmount = totalAmount.add(revenue);
182	        }
183	
184	        csv.append("total,").append(FormatterUtil.formatCurrencyCSV(totalAmount)).append("\n");
185	
186	        return csv.toString();
187	    }
188	}
189	package com.pousada.services;
190	
191	import com.pousada.models.Reservation;
192	import com.pousada.models.Room;
193	import com.pousada.repositories.ReservationRepository;
194	import com.pousada.repositories.RoomRepository;
195	import com.pousada.utils.DateUtil;
196	import com.pousada.utils.Money;
197	import java.math.BigDecimal;
198	import java.time.LocalDate;
199	
200	public class ReservationService {
201	    private final ReservationRepository reservationRepository;
202	    private final RoomRepository roomRepository;
203	
204	    public ReservationService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
205	        this.reservationRepository = reservationRepository;
206	        this.roomRepository = roomRepository;
207	    }
208	
209	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
210	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
211	                                        int guests, String ratePlan) throws Exception {
212	        Room room = roomRepository.findByNumber(roomNumber);
213	        if (room == null) {
214	            return null;
215	        }
216	
217	        if (guests < 1 || guests > room.getCapacity()) {
218	            throw new IllegalArgumentException("Invalid guest count");
219	        }
220	
221	        if (!checkIn.isBefore(checkOut)) {
222	            throw new IllegalArgumentException("Invalid dates");
223	        }
224	
225	        if (!reservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
226	            throw new IllegalArgumentException("Room unavailable");
227	        }
228	
229	        int nights = DateUtil.countNights(checkIn, checkOut);
230	        BigDecimal subtotal = calculateSubtotal(room.getNightlyRate(), checkIn, checkOut, nights);
231	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
232	        BigDecimal total = Money.subtract(subtotal, discount);
233	
234	        Reservation reservation = new Reservation();
235	        reservation.setRoomNumber(roomNumber);
236	        reservation.setGuestName(guestName);
237	        reservation.setGuestEmail(guestEmail);
238	        reservation.setGuestCpf(guestCpf);
239	        reservation.setCheckIn(checkIn);
240	        reservation.setCheckOut(checkOut);
241	        reservation.setGuests(guests);
242	        reservation.setRatePlan(ratePlan);
243	        reservation.setNights(nights);
244	        reservation.setSubtotal(subtotal);
245	        reservation.setDiscount(discount);
246	        reservation.setTotal(total);
247	        reservation.setStatus("PENDING");
248	        reservation.setAmountPaid(new BigDecimal("0.00"));
249	
250	        return reservationRepository.create(reservation);
251	    }
252	
253	    public Reservation confirmReservation(Long reservationId, BigDecimal amountPaid) throws Exception {
254	        Reservation reservation = reservationRepository.findById(reservationId);
255	        if (reservation == null) {
256	            return null;
257	        }
258	
259	        if (!"PENDING".equals(reservation.getStatus())) {
260	            throw new IllegalStateException("Cannot confirm a non-pending reservation");
261	        }
262	
263	        reservation.setStatus("CONFIRMED");
264	        reservation.setAmountPaid(amountPaid);
265	        reservationRepository.update(reservation);
266	
267	        return reservation;
268	    }
269	
270	    public Reservation checkIn(Long reservationId) throws Exception {
271	        Reservation reservation = reservationRepository.findById(reservationId);
272	        if (reservation == null) {
273	            return null;
274	        }
275	
276	        if (!"CONFIRMED".equals(reservation.getStatus())) {
277	            throw new IllegalStateException("Cannot check in a non-confirmed reservation");
278	        }
279	
280	        reservation.setStatus("CHECKED_IN");
281	        reservationRepository.update(reservation);
282	
283	        return reservation;
284	    }
285	
286	    public Reservation checkOut(Long reservationId) throws Exception {
287	        Reservation reservation = reservationRepository.findById(reservationId);
288	        if (reservation == null) {
289	            return null;
290	        }
291	
292	        if (!"CHECKED_IN".equals(reservation.getStatus())) {
293	            throw new IllegalStateException("Cannot check out a non-checked-in reservation");
294	        }
295	
296	        reservation.setStatus("CHECKED_OUT");
297	        reservationRepository.update(reservation);
298	
299	        return reservation;
300	    }
301	
302	    public Reservation cancelReservation(Long reservationId) throws Exception {
303	        Reservation reservation = reservationRepository.findById(reservationId);
304	        if (reservation == null) {
305	            return null;
306	        }
307	
308	        String status = reservation.getStatus();
309	        if (!"PENDING".equals(status) && !"CONFIRMED".equals(status)) {
310	            throw new IllegalStateException("Cannot cancel a reservation in this status");
311	        }
312	
313	        BigDecimal refund = BigDecimal.ZERO;
314	
315	        if ("CONFIRMED".equals(status)) {
316	            if ("STANDARD".equals(reservation.getRatePlan())) {
317	                refund = reservation.getAmountPaid();
318	            }
319	        }
320	
321	        reservation.setStatus("CANCELLED");
322	        reservation.setRefund(refund);
323	        reservationRepository.update(reservation);
324	
325	        return reservation;
326	    }
327	
328	    private BigDecimal calculateSubtotal(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, int nights) {
329	        BigDecimal total = BigDecimal.ZERO;
330	
331	        LocalDate currentDate = checkIn;
332	        while (currentDate.isBefore(checkOut)) {
333	            BigDecimal dailyRate = nightlyRate;
334	            if (DateUtil.isHighSeason(currentDate)) {
335	                dailyRate = Money.multiply(nightlyRate, new BigDecimal("1.20"));
336	            }
337	            total = Money.add(total, dailyRate);
338	            currentDate = currentDate.plusDays(1);
339	        }
340	
341	        return total;
342	    }
343	
344	    private BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
345	        if ("NON_REFUNDABLE".equals(ratePlan)) {
346	            return Money.percentage(subtotal, 15);
347	        }
348	        return BigDecimal.ZERO;
349	    }
350	}

