187	        this.database = database;
188	    }
189	
190	    public Reservation create(Reservation reservation) throws Exception {
191	        String sql = """
192	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
193	                                     check_in, check_out, guests, rate_plan, nights,
194	                                     subtotal, discount, total, status, amount_paid)
195	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
196	            """;
197	
198	        try (Connection conn = database.getConnection();
199	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
200	
201	            stmt.setInt(1, reservation.getRoomNumber());
202	            stmt.setString(2, reservation.getGuestName());
203	            stmt.setString(3, reservation.getGuestEmail());
204	            stmt.setString(4, reservation.getGuestCpf());
205	            stmt.setDate(5, java.sql.Date.valueOf(reservation.getCheckIn()));
206	            stmt.setDate(6, java.sql.Date.valueOf(reservation.getCheckOut()));
207	            stmt.setInt(7, reservation.getGuests());
208	            stmt.setString(8, reservation.getRatePlan());
209	            stmt.setInt(9, reservation.getNights());
210	            stmt.setBigDecimal(10, reservation.getSubtotal());
211	            stmt.setBigDecimal(11, reservation.getDiscount());
212	            stmt.setBigDecimal(12, reservation.getTotal());
213	            stmt.setString(13, reservation.getStatus());
214	            stmt.setBigDecimal(14, reservation.getAmountPaid());
215	
216	            stmt.executeUpdate();
217	
218	            try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
219	                if (generatedKeys.next()) {
220	                    reservation.setId(generatedKeys.getLong(1));
221	                }
222	            }
223	        }
224	
225	        return reservation;
