227	
228	    public Reservation findById(Long id) throws Exception {
229	        String sql = """
230	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
231	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
232	            FROM reservations WHERE id = ?
233	            """;
234	
235	        try (Connection conn = database.getConnection();
236	             PreparedStatement stmt = conn.prepareStatement(sql)) {
237	
238	            stmt.setLong(1, id);
239	            try (ResultSet rs = stmt.executeQuery()) {
240	                if (rs.next()) {
241	                    return mapRowToReservation(rs);
242	                }
243	            }
244	        }
245	
246	        return null;
247	    }
