249	    public void update(Reservation reservation) throws Exception {
250	        String sql = """
251	            UPDATE reservations
252	            SET status = ?, amount_paid = ?, refund = ?
253	            WHERE id = ?
254	            """;
255	
256	        try (Connection conn = database.getConnection();
257	             PreparedStatement stmt = conn.prepareStatement(sql)) {
258	
259	            stmt.setString(1, reservation.getStatus());
