268	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws Exception {
269	        String sql = """
270	            SELECT COUNT(*) as count FROM reservations
271	            WHERE room_number = ?
272	            AND status != 'CANCELLED'
273	            AND check_in < ? AND check_out > ?
274	            """;
275	
276	        try (Connection conn = database.getConnection();
277	             PreparedStatement stmt = conn.prepareStatement(sql)) {
278	
279	            stmt.setInt(1, roomNumber);
280	            stmt.setDate(2, java.sql.Date.valueOf(checkOut));
281	            stmt.setDate(3, java.sql.Date.valueOf(checkIn));
282	
283	            try (ResultSet rs = stmt.executeQuery()) {
284	                rs.next();
285	                return rs.getInt("count") == 0;
286	            }
287	        }
