290	    public List<Reservation> findByRoomAndNight(int roomNumber, LocalDate night) throws Exception {
291	        String sql = """
292	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
293	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
294	            FROM reservations
295	            WHERE room_number = ?
296	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
297	            AND check_in <= ? AND check_out > ?
298	            ORDER BY check_in
299	            """;
300	
301	        List<Reservation> reservations = new ArrayList<>();
302	
303	        try (Connection conn = database.getConnection();
304	             PreparedStatement stmt = conn.prepareStatement(sql)) {
305	
306	            stmt.setInt(1, roomNumber);
307	            stmt.setDate(2, java.sql.Date.valueOf(night));
308	            stmt.setDate(3, java.sql.Date.valueOf(night));
309	
310	            try (ResultSet rs = stmt.executeQuery()) {
311	                while (rs.next()) {
312	                    reservations.add(mapRowToReservation(rs));
313	                }
314	            }
315	        }
316	
317	        return reservations;
318	    }
319	
320	    public List<Reservation> findByMonthAndNotCancelled(int year, int month) throws Exception {
321	        String sql = """
322	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
323	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
324	            FROM reservations
325	            WHERE EXTRACT(YEAR FROM check_in) = ?
326	            AND EXTRACT(MONTH FROM check_in) = ?
327	            AND status != 'CANCELLED'
328	            ORDER BY check_in, id
329	            """;
330	
331	        List<Reservation> reservations = new ArrayList<>();
332	
333	        try (Connection conn = database.getConnection();
334	             PreparedStatement stmt = conn.prepareStatement(sql)) {
335	
336	            stmt.setInt(1, year);
337	            stmt.setInt(2, month);
338	
339	            try (ResultSet rs = stmt.executeQuery()) {
340	                while (rs.next()) {
341	                    reservations.add(mapRowToReservation(rs));
342	                }
343	            }
344	        }
345	
346	        return reservations;
347	    }
348	
349	    private Reservation mapRowToReservation(ResultSet rs) throws SQLException {
350	        Reservation r = new Reservation();
351	        r.setId(rs.getLong("id"));
352	        r.setRoomNumber(rs.getInt("room_number"));
353	        r.setGuestName(rs.getString("guest_name"));
354	        r.setGuestEmail(rs.getString("guest_email"));
355	        r.setGuestCpf(rs.getString("guest_cpf"));
356	        r.setCheckIn(rs.getDate("check_in").toLocalDate());
357	        r.setCheckOut(rs.getDate("check_out").toLocalDate());
358	        r.setGuests(rs.getInt("guests"));
359	        r.setRatePlan(rs.getString("rate_plan"));
360	        r.setNights(rs.getInt("nights"));
361	        r.setSubtotal(rs.getBigDecimal("subtotal"));
362	        r.setDiscount(rs.getBigDecimal("discount"));
363	        r.setTotal(rs.getBigDecimal("total"));
364	        r.setStatus(rs.getString("status"));
365	        r.setAmountPaid(rs.getBigDecimal("amount_paid"));
366	        r.setRefund(rs.getBigDecimal("refund"));
367	        return r;
368	    }
369	}
