 48	
 49	public class EmailValidator {
 50	    public static boolean isValid(String email) {
 51	        if (email == null || email.isEmpty()) {
 52	            return false;
 53	        }
 54	
 55	        int atCount = 0;
 56	        int atIndex = -1;
 57	
 58	        for (int i = 0; i < email.length(); i++) {
 59	            if (email.charAt(i) == '@') {
 60	                atCount++;
 61	                atIndex = i;
 62	            }
 63	        }
 64	
 65	        if (atCount != 1) {
 66	            return false;
 67	        }
 68	
 69	        if (atIndex == 0 || atIndex == email.length() - 1) {
 70	            return false;
 71	        }
 72	
 73	        String domain = email.substring(atIndex + 1);
 74	
 75	        int dotCount = 0;
 76	        for (char c : domain.toCharArray()) {
 77	            if (c == '.') {
 78	                dotCount++;
 79	            }
 80	        }
 81	
 82	        return dotCount >= 1 && !domain.startsWith(".") && !domain.endsWith(".");
 83	    }
 84	}
