127	import java.math.BigDecimal;
128	import java.math.RoundingMode;
129	
130	public class Money {
131	    private static final int SCALE = 2;
132	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
133	
134	    public static BigDecimal round(BigDecimal value) {
135	        return value.setScale(SCALE, ROUNDING_MODE);
136	    }
137	
138	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
139	        return round(a.add(b));
140	    }
141	
142	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
143	        return round(a.subtract(b));
144	    }
145	
146	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
147	        return round(a.multiply(b));
148	    }
149	
150	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
151	        return round(a.divide(b, SCALE, ROUNDING_MODE));
152	    }
153	
154	    public static BigDecimal percentage(BigDecimal value, int percent) {
155	        BigDecimal percentValue = new BigDecimal(percent).divide(new BigDecimal(100), SCALE, ROUNDING_MODE);
156	        return multiply(value, percentValue);
157	    }
158	}
